import{_ as l,l as r,o as t,c as p,v as e,p as s,x as o,d as n,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"热点修复","description":"","frontmatter":{"title":"热点修复","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hotspot-fix.md","filePath":"litho/hotspot-fix.md","lastUpdated":1789023840000}'),d={name:"litho/hotspot-fix.md"};function c(A,a,T,C,_,D){const i=r("Mermaid");return t(),p("div",null,[a[1]||(a[1]=e('<h1 id="热点修复" tabindex="-1">热点修复 <a class="header-anchor" href="#热点修复" aria-label="Permalink to &quot;热点修复&quot;">​</a></h1><div class="epigraph"><p>全芯片 OPC 收的是平均合同；真正死在良率上的是少数设计热点。修掩模、改设计还是改规则，是 DTCO 的选择，不是再跑一夜计算。</p><footer>—— 对照 DTCO 对 litho hotspot 的公开工程讨论</footer></div><p><a href="/litho/ml-opc">上一课</a>把学习模型限定为前向加速或初值，签核仍落在物理成像上。缺口是：物理 OPC 加 ML 暖启动之后，仍会留下局部不可印或窗口为零的图形——设计热点（hotspot）。本课钉热点修复。<a href="/litho/dtco-patterning">DTCO</a> 如何把修复反馈进库，下一课展开；这里先把「这一处怎么处理」钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全场 EPE 可以合格，SRAM 边角、标准单元拼接、密度跳变处仍出现桥接、断线、孔缩小。原因可能是模型外推、MRC 夹紧、禁戒节距、或设计本来就在窗口悬崖上。<a href="/litho/pw-opc">PW-OPC</a> 降低发生率，不保证零。ML 若在热点邻域外推，还会造出光滑的假安全。</p><p>热点不是检查器上的 MRC 红旗。MRC 绿、模拟却在角点死，或硅片 SEM 才看见。问题是检测–分类–处置的闭环，以及处置权在掩模还是在设计。</p><h3 id="三类处置不要混成「再-opc」" tabindex="-1">三类处置不要混成「再 OPC」 <a class="header-anchor" href="#三类处置不要混成「再-opc」" aria-label="Permalink to &quot;三类处置不要混成「再 OPC」&quot;">​</a></h3><p>掩模侧：局部 ILT、加密碎片、加/改 SRAF、定向修复。设计侧：改线端、加通孔冗余、挪绕线、换单元变体。工艺侧：改剂量/焦点中心、光源微调——牵动全场，很少为单点启用。把设计错误交给掩模硬扛，TAPOUT 会把窗口卖光。</p><p><span class="marginnote">热点清单必须带来源：纯模拟、在线检测、还是电性失效。三类的假阳性不同，修法不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检测：全芯片 PV-band、热点分类器（可含 ML，但要用物理再确认）、以及硅片上的工艺窗监测图形。分类：光学可修 / 须改设计 / 须改规则。可修的进局部逆问题，范围要盖住光学直径，否则边界再造新热点。须改设计的退回单元库或路由器，带上失败的工艺点图像，而不是只标一个坐标。</p><p>与 MRC 修复的分工：MRC 是可写性；热点是可印性。先夹紧再发现热点，可能是夹紧造成的，要回看 fixup 日志。先修热点再炸 MRC，则走回上一课。</p><h3 id="库与路由器" tabindex="-1">库与路由器 <a class="header-anchor" href="#库与路由器" aria-label="Permalink to &quot;库与路由器&quot;">​</a></h3><p>重复出现的热点说明单元或布线规则有洞。修复一万处相同的线端，不如改一版库。这就是 DTCO 的入口：热点统计驱动设计规则下一版，而不是 OPC 团队无限局部 ILT。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>热点是邻域算子的坏点：禁戒节距上对比崩溃、三维阴影把某一取向推下窗、刻蚀密度跳变。局部 ILT 能在透镜通带里找更好的形状，但自由度仍受 MRC 与写版约束。若物理上对比不足，掩模再弯也没有光子。那时必须放宽间距或改照明——后者是 SMO 级决策。</p><p>ML 分类器加速找点，不能当处置器。域外设计（新单元、新层）上的「热点分数」要物理复核，否则会漏报真点、狂报假点。</p><p><span class="marginnote">「修热点」在管理上要有冻结点：过了某日只允许掩模补丁，不准再改库。日历与物理要写在同一流程里。</span></p>',18)),(t(),s(E,null,{default:o(()=>[h(i,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%85%A8%E8%8A%AF%E7%89%87%20OPC%20%2F%20ML%20%E5%88%9D%E5%80%BC%22%5D%20--%3E%20DET%5B%22PV-band%20%E4%B8%8E%E7%83%AD%E7%82%B9%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20MASK%5B%22%E5%B1%80%E9%83%A8%20ILT%20%2F%20%E5%8A%A0%E5%AF%86%20OPC%22%5D%0A%20%20DET%20--%3E%20DES%5B%22%E6%94%B9%E5%8D%95%E5%85%83%20%2F%20%E7%BB%95%E7%BA%BF%22%5D%0A%20%20DET%20--%3E%20RULE%5B%22%E6%94%B9%E8%AE%BE%E8%AE%A1%E8%A7%84%E5%88%99%20%2F%20SMO%22%5D%0A%20%20MASK%20--%3E%20SIGN%5B%22%E7%89%A9%E7%90%86%E5%86%8D%E7%AD%BE%E6%A0%B8%22%5D%0A%20%20DES%20--%3E%20DTCO%5B%22DTCO%20%E5%9B%9E%E5%BA%93%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写具体单元轨道高度，也不把机器学习网络结构当修复算法。不要发明某节点的热点密度数字。后课默认：OPC 收敛之后还有热点清单，处置分掩模/设计/规则三轨。</p><p>硅片随机缺陷不是设计热点；剂量不足的泊松尾要胶与剂量预算，见随机效应课。</p><p><span class="marginnote">热点修复不是对客户版图的美化。未授权改设计会改时序。处置权必须在设计合同里写清。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全芯片均值合格后，良率仍死在局部热点。</li><li>处置分掩模局部逆、改设计、改规则/光源三轨，不要一律再 OPC。</li><li>ML 可找点，处置与签核必须物理。</li><li>重复热点应升级为 DTCO 改库，而不是万次局部补丁。</li><li>出处：DTCO 与 litho hotspot 的公开工程讨论。</li></ul>',6))])}const f=l(d,[["render",c]]);export{P as __pageData,f as default};
